/*
** 2026 November 11
**
** This file contains code to repair RTF that holds unescaped UTF-8.
**
** RTF is a 7-bit format.  A character outside of ASCII is supposed to
** be written as an escape, either \'hh for a byte in some code page or
** \uN for a Unicode value.  But RTF is often generated by programs
** that paste text into a template, and when the text is UTF-8 the
** result is a file with bytes above 127 in it.  Such files are not
** valid RTF but they are common enough.
**
** Cocoa reads a stray byte above 127 as a character in the Windows
** code page.  For UTF-8 that gives the wrong characters at best.  At
** worst, when one of the bytes is not assigned in the code page, the
** whole passage that contains it is silently discarded.  In an editor
** that saves automatically, that would destroy the text of the file.
**
** The routine in this file detects UTF-8 in RTF and rewrites it as \uN
** escapes, so that the text is read as its author intended.
**
** This file is portable C and makes no use of Cocoa.
*/
#include "bestedit.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/*
** Maximum depth to which RTF groups may nest in a file that is to be
** repaired.  Real files nest only a few levels deep.
*/
#define RTF_MX_DEPTH 200

/*
** If the bytes at z[0..n-1] begin with a well-formed UTF-8 encoding of
** a character that is not ASCII, write the character to *pChar and
** return the number of bytes in its encoding, which is between 2 and
** 4.  Otherwise return 0.
**
** Encodings that are longer than necessary, encodings of surrogates,
** and encodings of values beyond the end of Unicode are not
** well-formed.
*/
static int rtfUtf8(const unsigned char *z, i64 n, unsigned int *pChar){
  unsigned int c = z[0];
  int nByte;                      /* Length of the encoding */
  int i;                          /* Loop counter */

  if( c<0xc2 || c>0xf4 ) return 0;
  nByte = c<0xe0 ? 2 : c<0xf0 ? 3 : 4;
  if( n<nByte ) return 0;
  c &= 0xff >> (nByte+1);
  for(i=1; i<nByte; i++){
    if( (z[i] & 0xc0)!=0x80 ) return 0;
    c = (c<<6) | (z[i] & 0x3f);
  }
  if( nByte==3 && (c<0x800 || (c>=0xd800 && c<=0xdfff)) ) return 0;
  if( nByte==4 && (c<0x10000 || c>0x10ffff) ) return 0;
  *pChar = c;
  return nByte;
}

/*
** Append to z[] the escape for UTF-16 code unit c, followed by nSkip
** placeholder characters, and return the number of bytes appended.
**
** The parameter of \u is a signed 16-bit number.  The space that ends
** the control word is not part of the text.  A reader that understands
** \u discards the nSkip characters that follow it; they are there for
** the benefit of readers that do not.
*/
static int rtfEscape(char *z, unsigned int c, int nSkip){
  int n = sprintf(z, "\\u%d ", c>=0x8000 ? (int)c - 0x10000 : (int)c);
  while( nSkip-- > 0 ) z[n++] = '?';
  return n;
}

/*
** Examine the n bytes of RTF at zIn[].  If they contain UTF-8 that has
** not been escaped, return a corrected copy in memory obtained from
** malloc() and write its size to *pnOut.  The caller must free it.
**
** Return NULL if there is nothing to repair, which is the usual case,
** or if the input does not qualify.  To qualify, every byte above 127
** in the input must be part of well-formed UTF-8.  A file in which
** even one such byte is not, is presumed to hold text in some other
** encoding and is left for the RTF reader to interpret.  Files that
** contain binary data (the \bin control word) do not qualify either.
**
** The number of placeholder characters that a reader skips after \u is
** set by the \uc control word, and that setting is local to the
** enclosing group.  So this routine has to follow the group structure
** of the document, and the control words in it, in order to know how
** many placeholders to write.
*/
char *beRtfRepair(const char *zIn, i64 n, i64 *pnOut){
  const unsigned char *z = (const unsigned char*)zIn;
  char *zOut;                     /* The result */
  i64 nHigh = 0;                  /* Number of bytes above 127 */
  i64 i;                          /* Index into z[] */
  i64 j = 0;                      /* Index into zOut[] */
  int aSkip[RTF_MX_DEPTH];        /* Value of \uc in each open group */
  int iDepth = 0;                 /* Number of open groups */
  unsigned int c;                 /* A character */

  /* Pass 1: Decide whether the input qualifies. */
  for(i=0; i<n; i++){
    int nByte;
    if( z[i]<0x80 ) continue;
    nByte = rtfUtf8(&z[i], n-i, &c);
    if( nByte==0 ) return 0;
    nHigh += nByte;
    i += nByte-1;
  }
  if( nHigh==0 ) return 0;
  for(i=0; i+4<n; i++){
    if( z[i]=='\\' && memcmp(&z[i], "\\bin", 4)==0
     && (z[i+4]<'a' || z[i+4]>'z') ){
      return 0;
    }
  }

  /* Pass 2: Copy the input, replacing UTF-8 with escapes.  The longest
  ** escape, for a character that takes two code units when the reader
  ** skips many placeholders, is under 8 bytes of output per byte of
  ** input so long as \uc is small.  Larger values of \uc are not
  ** believed to exist; a file that uses one does not qualify. */
  zOut = malloc( (size_t)(n + nHigh*8 + 1) );
  if( zOut==0 ) return 0;
  aSkip[0] = 1;
  for(i=0; i<n; i++){
    if( z[i]=='{' ){
      if( iDepth+1>=RTF_MX_DEPTH ) goto no_repair;
      aSkip[iDepth+1] = aSkip[iDepth];
      iDepth++;
      zOut[j++] = '{';
    }else if( z[i]=='}' ){
      if( iDepth>0 ) iDepth--;
      zOut[j++] = '}';
    }else if( z[i]=='\\' && i+1<n ){
      i64 iStart = i;             /* Start of the control word */
      i++;
      if( (z[i]>='a' && z[i]<='z') || (z[i]>='A' && z[i]<='Z') ){
        i64 iParam;               /* Start of the numeric parameter */
        while( i<n && ((z[i]>='a' && z[i]<='z') || (z[i]>='A' && z[i]<='Z')) ){
          i++;
        }
        iParam = i;
        if( i<n && z[i]=='-' ) i++;
        while( i<n && z[i]>='0' && z[i]<='9' ) i++;
        if( iParam-iStart==3 && memcmp(&z[iStart], "\\uc", 3)==0
         && i>iParam ){
          int nSkip = atoi((const char*)&z[iParam]);
          if( nSkip<0 || nSkip>4 ) goto no_repair;
          aSkip[iDepth] = nSkip;
        }
        if( i<n && z[i]==' ' ) i++;
      }else{
        /* A control symbol.  \'hh is followed by two more bytes. */
        if( z[i]=='\'' ) i += 2;
        i++;
        if( i>n ) i = n;
      }
      memcpy(&zOut[j], &z[iStart], (size_t)(i-iStart));
      j += i-iStart;
      i--;
    }else if( z[i]<0x80 ){
      zOut[j++] = (char)z[i];
    }else{
      int nByte = rtfUtf8(&z[i], n-i, &c);
      if( nByte==0 ) goto no_repair;
      if( c>=0x10000 ){
        c -= 0x10000;
        j += rtfEscape(&zOut[j], 0xd800 + (c>>10), aSkip[iDepth]);
        j += rtfEscape(&zOut[j], 0xdc00 + (c&0x3ff), aSkip[iDepth]);
      }else{
        j += rtfEscape(&zOut[j], c, aSkip[iDepth]);
      }
      i += nByte-1;
    }
  }
  zOut[j] = 0;
  *pnOut = j;
  return zOut;

no_repair:
  free(zOut);
  return 0;
}
